"""Rasa hosted A2A agent: a2a-sdk ``AgentExecutor`` for the Sanic integration.

Used when ``a2a_server`` is configured in ``endpoints.yml`` so external
orchestrators can invoke this Rasa assistant as an A2A agent. Not used for the
outbound A2A client role (``rasa.agents.protocol.a2a.A2AAgent`` in flows).
"""

from __future__ import annotations

import asyncio
from typing import TYPE_CHECKING, Any

import structlog
from a2a.server.agent_execution import AgentExecutor, RequestContext
from a2a.server.events import EventQueue
from a2a.server.tasks import InMemoryTaskStore
from a2a.server.tasks.task_updater import TaskUpdater
from a2a.types import (
    AgentCapabilities,
    AgentCard,
    CancelTaskRequest,
    Role,
    Task,
    TaskState,
    TaskStatus,
    TaskStatusUpdateEvent,
)
from pydantic import BaseModel, ConfigDict, Field, SkipValidation

from rasa.core.a2a_server.a2a_message_cache import (
    A2AMessageCache,
    DedupRecordingTaskStore,
)
from rasa.core.a2a_server.a2a_output_channel import A2AOutputChannel
from rasa.core.a2a_server.a2a_task_event_publisher import (
    A2ATaskEventPublisher,
    A2ATaskPublishOperation,
    publish_task_canceled,
    publish_task_failure,
)
from rasa.core.a2a_server.agent_card_generator import jsonrpc_supported_interfaces
from rasa.core.a2a_server.config import (
    DEFAULT_A2A_TASK_TIMEOUT_SECONDS,
    A2AServerSettings,
)
from rasa.core.a2a_server.context_guard import (
    CONTEXT_LIMIT_EXCEEDED_ERROR,
    A2AContextGuard,
    ContextLimitExceeded,
)
from rasa.core.a2a_server.engine_adapter import A2AEngineAdapter
from rasa.core.a2a_server.proto_convert import as_plain_dict
from rasa.core.a2a_server.push_notification_transport import (
    A2APushNotificationTransport,
    create_push_notification_transport,
)
from rasa.core.a2a_server.rasa_a2a_request_handler import (
    STREAMING_CALLER_STATE_KEY,
    RasaA2ARequestHandler,
)
from rasa.core.agent import Agent
from rasa.core.channels.channel import UserMessage
from rasa.core.constants import (
    A2A_CLIENT_SLOT_COMMANDS_METADATA_KEY,
    RASA_A2A_INPUT_CHANNEL,
)

if TYPE_CHECKING:
    from a2a.server.context import ServerCallContext

structlogger = structlog.get_logger()

# How long ``cancel()`` waits for an interrupted turn to wind down before it
# returns and lets the SDK cancel the producer, and how long the cancelled turn
# then gets to cancel its flow. Together they must stay well below
# ``a2a_message_cache.IN_FLIGHT_GRACE_SECONDS``: the timeout handler's terminal
# save has to land inside that window, or a retry of the same ``messageId``
# would run the turn again.
INTERRUPT_WAIT_SECONDS = 10.0
FORCED_CANCEL_CLEANUP_SECONDS = 10.0

_AGENT_NOT_READY_MESSAGE = "Agent is not ready to handle messages."
_HANDLE_MESSAGE_FAILED_ERROR = (
    "Failed to process message because Agent.handle_message() raised an error."
)
_TASK_CYCLE_NOT_CLOSED_ERROR = (
    "Failed to process message because the output "
    "channel did not close the task cycle."
)


def _default_handler_card(config: A2AServerSettings | None) -> AgentCard:
    """Card stored on the handler when the caller has not resolved one yet."""
    if config is not None:
        from rasa.core.a2a_server.bootstrap import resolve_agent_card

        return resolve_agent_card(config)
    return AgentCard(
        name="Rasa Agent",
        description="Rasa agent",
        supported_interfaces=jsonrpc_supported_interfaces("http://localhost:5005/"),
        version="1.0.0",
        default_input_modes=["text", "text/plain"],
        default_output_modes=["text", "text/plain"],
        capabilities=AgentCapabilities(streaming=True),
    )


async def _enqueue_opening_task(
    context: RequestContext,
    event_queue: EventQueue,
    task_id: str,
    context_id: str,
) -> None:
    """Enqueue a ``Task`` before any status or artifact event.

    ``ActiveTask`` rejects a status update that arrives first. A second ``Task``
    for an id that already exists is ignored by the consumer, which also drops
    the user message it was about to append to the task history. For a
    follow-up on an existing task, a ``submitted`` status update goes first so
    that message is persisted.

    The ``Task`` is still enqueued for a follow-up: the request handler waits
    for it (by the message id in its history) to tell this request's events
    from those of a request that ran before it on the same task.

    The inbound ``Message.metadata`` (for example ``sender_id`` from a Rasa
    orchestrator) is copied onto ``Task.metadata``. This opening task is the
    only full task a push callback receives; later 1.0 ``statusUpdate`` /
    ``artifactUpdate`` events carry no task metadata, so the receiver routes
    them with the metadata learned from this task.
    """
    message = context.message
    task = Task(
        id=task_id,
        context_id=context_id,
        status=TaskStatus(state=TaskState.TASK_STATE_SUBMITTED),
    )
    if message is not None:
        if message.role == Role.ROLE_USER and len(message.parts) > 0:
            task.history.add().CopyFrom(message)
        if message.metadata:
            task.metadata.CopyFrom(message.metadata)
    if context.current_task is not None:
        await event_queue.enqueue_event(
            TaskStatusUpdateEvent(
                task_id=task_id,
                context_id=context_id,
                status=TaskStatus(state=TaskState.TASK_STATE_SUBMITTED),
            )
        )
    await event_queue.enqueue_event(task)


def _caller_requested_streaming(context: RequestContext) -> bool:
    """Whether this request asked for token streaming.

    A missing call context or flag keeps today's behaviour and streams. The
    request handler is the only writer of this flag, so a present value is
    that boolean. Idle cancel does not use this: that turn emits no streamed
    utterances.
    """
    call_context = context.call_context
    if call_context is None:
        return True
    return call_context.state.get(STREAMING_CALLER_STATE_KEY, True)


def _resolve_message_cache_ttl_seconds(
    message_cache_ttl_seconds: int | None,
    task_timeout_seconds: int | None,
) -> int:
    """Resolve cache TTL; ``0`` is explicit (immediate expiry), not a missing value."""
    if message_cache_ttl_seconds is not None:
        return message_cache_ttl_seconds
    if task_timeout_seconds is not None:
        return task_timeout_seconds
    return DEFAULT_A2A_TASK_TIMEOUT_SECONDS


class _ActiveTurn(BaseModel):
    """In-flight ``execute()`` state for one A2A ``task_id``."""

    model_config = ConfigDict(arbitrary_types_allowed=True)

    task_id: str
    context_id: str
    # Snapshotted when the turn is registered. ``rebind()`` replaces the
    # executor's agent for later turns; this turn keeps the ones it started with.
    # Both are trusted internal objects. ``A2AEngineAdapter`` is a Protocol,
    # which Pydantic cannot ``isinstance``, so validation is skipped.
    agent: SkipValidation[Agent]
    engine_adapter: SkipValidation[A2AEngineAdapter]
    done: asyncio.Event = Field(default_factory=asyncio.Event)
    output_channel: A2AOutputChannel | None = None
    cancel_requested: bool = False


class _ExecuteTurnState(BaseModel):
    """Mutable state accumulated while ``execute()`` runs one message turn."""

    model_config = ConfigDict(arbitrary_types_allowed=True)

    updater: TaskUpdater
    output_channel: A2AOutputChannel | None = None
    published_terminal_state: TaskState | None = None


class RasaA2AAgentExecutor(AgentExecutor):
    """Executes inbound A2A requests against a Rasa ``Agent``.

    In-flight ``execute()`` work is tracked per A2A ``task_id`` (one message/task
    cycle). ``context_id`` is the orchestrator session id and becomes Rasa
    ``sender_id``.     Orchestrator ``cancel()`` and per-``task_id`` wall-clock timeouts
    signal in-flight tasks via ``cancel_background_tasks``, orchestrator-cancel
    flags on the matching ``A2AOutputChannel``, and the engine adapter.
    Timeouts are a safety net; explicit ``cancel()`` / ``tasks/cancel`` is primary.
    """

    def __init__(
        self,
        agent: Agent,
        *,
        engine_adapter: A2AEngineAdapter,
        task_timeout_seconds: int | None = DEFAULT_A2A_TASK_TIMEOUT_SECONDS,
        message_cache_ttl_seconds: int | None = None,
        max_contexts: int | None = None,
        a2a_server_config: A2AServerSettings | None = None,
        push_transport: A2APushNotificationTransport | None = None,
        agent_card: AgentCard | None = None,
    ) -> None:
        self._agent = agent
        self._engine_adapter = engine_adapter
        self._task_timeout_seconds = task_timeout_seconds
        self._context_guard = A2AContextGuard(max_contexts=max_contexts)
        self._active_turns_by_task_id: dict[str, _ActiveTurn] = {}
        self._task_timeout_tasks: dict[str, asyncio.Task[None]] = {}
        self._registry_lock = asyncio.Lock()
        ttl = _resolve_message_cache_ttl_seconds(
            message_cache_ttl_seconds, task_timeout_seconds
        )
        in_flight_timeout = (
            task_timeout_seconds if task_timeout_seconds is not None else ttl
        )
        self._message_cache = A2AMessageCache(
            ttl_seconds=ttl,
            in_flight_timeout_seconds=in_flight_timeout,
        )

        self._push_transport: A2APushNotificationTransport | None
        if push_transport is not None:
            self._push_transport = push_transport
        elif a2a_server_config is not None:
            self._push_transport = create_push_notification_transport(a2a_server_config)
        else:
            self._push_transport = None
        push_config_store = (
            self._push_transport.config_store if self._push_transport else None
        )
        push_sender = self._push_transport.notifier if self._push_transport else None
        push_url_validator = (
            self._push_transport.url_validator if self._push_transport else None
        )

        self._request_handler = RasaA2ARequestHandler(
            agent_executor=self,
            task_store=DedupRecordingTaskStore(
                InMemoryTaskStore(), self._message_cache
            ),
            agent_card=agent_card or _default_handler_card(a2a_server_config),
            message_cache=self._message_cache,
            context_guard=self._context_guard,
            push_config_store=push_config_store,
            push_sender=push_sender,
            push_url_validator=push_url_validator,
        )

    @property
    def request_handler(self) -> RasaA2ARequestHandler:
        """Transport-agnostic request handler used by the A2A JSON-RPC layer."""
        return self._request_handler

    async def rebind(
        self, agent: Agent, engine_adapter: A2AEngineAdapter
    ) -> list[asyncio.Event]:
        """Serve later turns from a hot-swapped model.

        Returns the ``done`` events of turns already in ``execute()``. Those
        turns keep the agent and adapter they registered with. The caller
        closes that agent only after every returned event is set. The request
        handler, task store, message cache, and context guard stay as they are.

        Rebind does not start CALM ``pattern_code_change``. The next CALM
        turn on the swapped model still runs the processor stale-flow purge,
        which inserts a code-change frame when flow fingerprints differ.
        Mantle does not purge stale frames on a turn yet (ENG-2820).
        Whether Mantle needs a default skill in that role is ENG-3545.
        """
        async with self._registry_lock:
            pending = [
                turn.done
                for turn in self._active_turns_by_task_id.values()
                if turn.agent is self._agent
            ]
            self._agent = agent
            self._engine_adapter = engine_adapter
            return pending

    def update_agent_card(self, agent_card: AgentCard) -> None:
        """Point the JSON-RPC handler at the card for the current model."""
        self._request_handler.set_agent_card(agent_card)

    @property
    def message_cache(self) -> A2AMessageCache:
        return self._message_cache

    @property
    def push_transport(self) -> A2APushNotificationTransport | None:
        """Push config store and HTTP callback sender for task state updates."""
        return self._push_transport

    @property
    def active_task_count(self) -> int:
        """Number of in-flight ``execute()`` calls (one entry per ``task_id``)."""
        return len(self._active_turns_by_task_id)

    @property
    def active_context_count(self) -> int:
        """Number of ``context_id`` sessions reserved (including ``input_required``)."""
        return self._context_guard.active_context_count

    @property
    def context_guard(self) -> A2AContextGuard:
        """Session cap and concurrent-context tracking for tests and introspection."""
        return self._context_guard

    def get_active_task_ids_for_context(self, context_id: str) -> list[str]:
        """Return in-flight ``task_id`` values for ``context_id``."""
        return [
            task_id
            for task_id, turn in self._active_turns_by_task_id.items()
            if turn.context_id == context_id
        ]

    async def execute(self, context: RequestContext, event_queue: EventQueue) -> None:
        """Handle an inbound A2A message by running the Rasa ``Agent``.

        Uses ``context.context_id`` as Rasa ``sender_id`` and publishes task
        lifecycle events to ``event_queue`` via ``TaskUpdater``.
        """
        ids = self._execute_context_ids(context)
        if ids is None:
            return
        context_id, task_id = ids
        await _enqueue_opening_task(context, event_queue, task_id, context_id)

        turn = _ExecuteTurnState(updater=TaskUpdater(event_queue, task_id, context_id))
        try:
            await self._context_guard.begin_turn(context_id, metadata=context.metadata)
        except ContextLimitExceeded:
            # The request handler rejects over-limit sends before a turn starts,
            # but its check reserves nothing: concurrent new contexts can all
            # pass it and only this reservation is atomic.
            structlogger.warning(
                "a2a_server.rasa_a2a_agent_executor.execute.context_limit",
                context_id=context_id,
                task_id=task_id,
                active_context_count=self._context_guard.active_context_count,
                max_contexts=self._context_guard.max_contexts,
            )
            await publish_task_failure(
                turn.updater, message=CONTEXT_LIMIT_EXCEEDED_ERROR
            )
            turn.published_terminal_state = TaskState.TASK_STATE_FAILED
            await self._finalize_turn(
                context_id,
                task_id,
                turn_state=turn,
                active_turn=None,
            )
            return

        active_turn = await self._register_active_turn(task_id, context_id)
        self._schedule_task_timeout(task_id, context_id, context.call_context)
        try:
            if await self._execute_reject_invalid_input(context, turn):
                return
            if await self._execute_reject_agent_not_ready(
                context_id, task_id, turn, active_turn.agent
            ):
                return
            await self._execute_run_agent_turn(
                context, context_id, task_id, turn, active_turn
            )
        except asyncio.CancelledError:
            await self._finish_forced_cancel(context_id, task_id, turn, active_turn)
            raise
        except Exception:
            await self._execute_on_handle_message_error(
                context_id, task_id, turn, active_turn
            )
        finally:
            await self._finalize_turn(
                context_id, task_id, turn_state=turn, active_turn=active_turn
            )

    async def cancel(self, context: RequestContext, event_queue: EventQueue) -> None:
        """Handle an inbound A2A cancel request.

        Signals in-flight ``execute()`` work for the requested ``task_id``,
        and publishes a terminal ``canceled`` event when no turn is already
        finalizing that task. Pattern-utterance policy comes from the adapter.
        """
        context_id = self._cancel_context_id(context)
        if context_id is None:
            return

        if await self._cancel_signal_in_flight_turn(context_id, context.task_id):
            return
        await self._cancel_idle_context(context_id, context.task_id, event_queue)

    async def close(self) -> None:
        """Drain in-flight A2A work and clear turn, context and dedup state.

        The request handler cancels every producer first, so each interrupted
        ``execute()`` unwinds through its own finalizer before the shared
        state below is cleared.
        """
        for task_id in list(self._task_timeout_tasks):
            self._cancel_task_timeout(task_id)

        await self._request_handler.aclose()

        async with self._registry_lock:
            # Retirement waits on these events. Clearing the registry without
            # setting them would leave that wait running after shutdown.
            for turn in self._active_turns_by_task_id.values():
                turn.done.set()
            self._active_turns_by_task_id.clear()

        await self._context_guard.clear()
        await self._message_cache.close()
        if self._push_transport is not None:
            await self._push_transport.close()

    # -- In-flight turn registry (keyed by ``task_id``) -------------------------

    async def _register_active_turn(self, task_id: str, context_id: str) -> _ActiveTurn:
        async with self._registry_lock:
            turn = _ActiveTurn(
                task_id=task_id,
                context_id=context_id,
                agent=self._agent,
                engine_adapter=self._engine_adapter,
            )
            self._active_turns_by_task_id[task_id] = turn
            return turn

    async def _set_active_turn_output_channel(
        self, task_id: str, output_channel: A2AOutputChannel
    ) -> None:
        async with self._registry_lock:
            turn = self._active_turns_by_task_id.get(task_id)
            if turn is not None:
                turn.output_channel = output_channel
                if turn.cancel_requested:
                    output_channel.begin_orchestrator_cancel_turn()

    async def _unregister_active_turn(self, task_id: str, turn: _ActiveTurn) -> None:
        async with self._registry_lock:
            existing = self._active_turns_by_task_id.get(task_id)
            if existing is turn:
                del self._active_turns_by_task_id[task_id]
        turn.done.set()

    async def _get_active_turn(self, task_id: str) -> _ActiveTurn | None:
        async with self._registry_lock:
            return self._active_turns_by_task_id.get(task_id)

    # -- Per-task wall-clock timeout (safety net) ---------------------------------

    def _schedule_task_timeout(
        self,
        task_id: str,
        context_id: str,
        call_context: ServerCallContext | None = None,
    ) -> None:
        if self._task_timeout_seconds is None:
            return

        async def _fire() -> None:
            await asyncio.sleep(self._task_timeout_seconds)
            # Cancelling the producer finalizes the turn, which cancels this
            # task's timer. Untrack it first so that finalizer cannot cancel
            # the timeout handler halfway through its own cancel.
            if self._task_timeout_tasks.get(task_id) is asyncio.current_task():
                del self._task_timeout_tasks[task_id]
            await self._handle_task_timeout(task_id, context_id, call_context)

        self._cancel_task_timeout(task_id)
        self._task_timeout_tasks[task_id] = asyncio.create_task(_fire())

    def _cancel_task_timeout(self, task_id: str) -> None:
        task = self._task_timeout_tasks.pop(task_id, None)
        if task is not None and not task.done():
            task.cancel()

    async def _handle_task_timeout(
        self,
        task_id: str,
        context_id: str,
        call_context: ServerCallContext | None,
    ) -> None:
        if await self._get_active_turn(task_id) is None:
            return
        structlogger.warning(
            "a2a_server.rasa_a2a_agent_executor.task_timeout",
            context_id=context_id,
            task_id=task_id,
            timeout_seconds=self._task_timeout_seconds,
        )
        if call_context is not None and await self._cancel_through_handler(
            task_id, call_context
        ):
            return
        await self._interrupt_in_flight_turn(task_id)

    async def _cancel_through_handler(
        self, task_id: str, call_context: ServerCallContext
    ) -> bool:
        """Cancel ``task_id`` the way ``tasks/cancel`` does.

        The SDK also cancels a producer that ignores the interrupt. It keeps
        that turn's producer, consumer and queue-sink asyncio tasks parked
        until the handler is closed, so a non-cooperative turn costs a few idle
        tasks until shutdown. The SDK offers no public way to release them
        earlier.

        Returns ``False`` when the handler could not cancel (for example the
        turn was not started through it), so the caller can interrupt directly.
        """
        try:
            await self._request_handler.on_cancel_task(
                CancelTaskRequest(id=task_id), call_context
            )
        except Exception as exc:
            structlogger.warning(
                "a2a_server.rasa_a2a_agent_executor.task_timeout_cancel_failed",
                task_id=task_id,
                error=str(exc),
            )
            return False
        return True

    # -- Orchestrator cancel (signal and post-message finalize) -----------------

    async def _interrupt_in_flight_turn(self, task_id: str) -> None:
        """Signal phase: mark cancel on the task channel and stop background work."""
        turn = await self._get_active_turn(task_id)
        if turn is not None:
            turn.cancel_requested = True
            if turn.output_channel is not None:
                turn.output_channel.begin_orchestrator_cancel_turn()
            # The turn's agent, not ``self._agent``: a model swap must not
            # signal the replacement while this turn is still running.
            if turn.agent is not None:
                turn.agent.cancel_background_tasks(turn.context_id)
            try:
                await asyncio.wait_for(turn.done.wait(), INTERRUPT_WAIT_SECONDS)
            except asyncio.TimeoutError:
                structlogger.warning(
                    "a2a_server.rasa_a2a_agent_executor.interrupt_timed_out",
                    task_id=task_id,
                    context_id=turn.context_id,
                    wait_seconds=INTERRUPT_WAIT_SECONDS,
                )

    async def _finish_forced_cancel(
        self,
        context_id: str,
        task_id: str,
        turn: _ExecuteTurnState,
        active_turn: _ActiveTurn,
    ) -> None:
        """Close a turn the SDK cancelled because it ignored the interrupt.

        On a ``tasks/cancel`` or timeout, cancel the active flow first, as a
        cooperative cancel does after ``handle_message``, so the next message
        on the context does not resume a flow the task reported as canceled.
        Shutdown cancels producers without a cancel request and leaves the
        dialogue alone.

        ``canceled`` is published while the event queue is still open: the
        SDK's own CANCELED write lands only in the store after the subscriber
        queues close, so a stream would otherwise end without a terminal event.
        """
        channel = turn.output_channel
        if (
            channel is not None
            and channel.cancel_turn_context is not None
            and not channel.task_cycle_closed
        ):
            try:
                await asyncio.wait_for(
                    self._finish_cancel_after_message_if_signaled(
                        context_id, channel, active_turn.engine_adapter
                    ),
                    FORCED_CANCEL_CLEANUP_SECONDS,
                )
            except Exception:
                structlogger.warning(
                    "a2a_server.rasa_a2a_agent_executor.forced_cancel_cleanup_failed",
                    task_id=task_id,
                    context_id=context_id,
                    exc_info=True,
                )
        await publish_task_canceled(turn.updater)
        turn.published_terminal_state = TaskState.TASK_STATE_CANCELED

    async def _finish_cancel_after_message_if_signaled(
        self,
        context_id: str,
        output_channel: A2AOutputChannel,
        engine_adapter: A2AEngineAdapter,
    ) -> None:
        """Run engine cancel when this turn was signaled before it finished.

        ``engine_adapter`` is the one this turn started with. It still holds
        that turn's agent after a model swap replaces ``self._engine_adapter``.
        """
        if output_channel.cancel_turn_context is None:
            return
        await engine_adapter.cancel_active_work(context_id, output_channel)

    # -- ``execute()`` helpers --------------------------------------------------

    def _execute_context_ids(self, context: RequestContext) -> tuple[str, str] | None:
        context_id = context.context_id
        task_id = context.task_id
        if context_id and task_id:
            return context_id, task_id
        structlogger.warning(
            "a2a_server.rasa_a2a_agent_executor.execute.missing_context_id",
            task_id=context.task_id,
            context_id=context_id,
        )
        return None

    async def _finalize_turn(
        self,
        context_id: str,
        task_id: str,
        *,
        turn_state: _ExecuteTurnState,
        active_turn: _ActiveTurn | None,
    ) -> None:
        if active_turn is not None:
            await self._unregister_active_turn(task_id, active_turn)
            self._cancel_task_timeout(task_id)

        terminal_state = turn_state.published_terminal_state
        if (
            turn_state.output_channel is not None
            and turn_state.output_channel.task_cycle_closed
        ):
            terminal_state = turn_state.output_channel.published_task_state

        await self._context_guard.end_turn(context_id, terminal_state=terminal_state)

    async def _execute_reject_invalid_input(
        self, context: RequestContext, turn: _ExecuteTurnState
    ) -> bool:
        """Return ``True`` when the turn should stop (failure already published)."""
        if context.get_user_input().strip():
            return False
        await publish_task_failure(turn.updater, message="Empty user message.")
        turn.published_terminal_state = TaskState.TASK_STATE_FAILED
        return True

    async def _execute_reject_agent_not_ready(
        self,
        context_id: str,
        task_id: str,
        turn: _ExecuteTurnState,
        agent: Agent,
    ) -> bool:
        if agent.is_ready():
            return False
        structlogger.warning(
            "a2a_server.rasa_a2a_agent_executor.execute.agent_not_ready",
            task_id=task_id,
            context_id=context_id,
        )
        await publish_task_failure(turn.updater, message=_AGENT_NOT_READY_MESSAGE)
        turn.published_terminal_state = TaskState.TASK_STATE_FAILED
        return True

    async def _execute_run_agent_turn(
        self,
        context: RequestContext,
        context_id: str,
        task_id: str,
        turn: _ExecuteTurnState,
        bound: _ActiveTurn,
    ) -> None:
        # 0.3 streams this as a TaskStatusUpdateEvent (state "submitted",
        # final false). The opening Task is a separate event and does not
        # replace it.
        agent = bound.agent
        engine_adapter = bound.engine_adapter
        await A2ATaskEventPublisher(turn.updater).publish_non_terminal(
            A2ATaskPublishOperation.SUBMIT,
            lambda: turn.updater.submit(),
        )
        turn.output_channel = A2AOutputChannel(
            turn.updater,
            context_id,
            engine_adapter=engine_adapter,
            streaming=_caller_requested_streaming(context),
        )
        await self._set_active_turn_output_channel(task_id, turn.output_channel)
        user_message = self._build_user_message_for_context(
            context, context_id, turn.output_channel, engine_adapter
        )
        await agent.handle_message(user_message)
        await self._finish_cancel_after_message_if_signaled(
            context_id, turn.output_channel, engine_adapter
        )
        if not turn.output_channel.task_cycle_closed:
            await publish_task_failure(
                turn.updater, message=_TASK_CYCLE_NOT_CLOSED_ERROR
            )
            turn.published_terminal_state = TaskState.TASK_STATE_FAILED

    @staticmethod
    def _request_metadata(context: RequestContext) -> dict[str, Any]:
        """Merge JSON-RPC and message metadata for adapter input."""
        metadata = as_plain_dict(context.metadata)
        message = context.message
        if message is not None and message.metadata:
            metadata.update(as_plain_dict(message.metadata))
        return metadata

    def _build_user_message_for_context(
        self,
        context: RequestContext,
        context_id: str,
        output_channel: A2AOutputChannel,
        engine_adapter: A2AEngineAdapter,
    ) -> UserMessage:
        """Build ``UserMessage`` with optional A2A client slot commands in metadata."""
        user_text = context.get_user_input().strip()
        request_metadata = self._request_metadata(context)
        user_metadata: dict[str, Any] = (
            dict(request_metadata) if request_metadata else {}
        )
        # Prevent clients from injecting internal slot command metadata.
        user_metadata.pop(A2A_CLIENT_SLOT_COMMANDS_METADATA_KEY, None)
        prepared = engine_adapter.prepare_input(
            context.message, user_text, user_metadata
        )
        return UserMessage(
            text=prepared.text,
            sender_id=context_id,
            input_channel=RASA_A2A_INPUT_CHANNEL,
            output_channel=output_channel,
            metadata=prepared.metadata,
        )

    async def _execute_on_handle_message_error(
        self,
        context_id: str,
        task_id: str,
        turn: _ExecuteTurnState,
        bound: _ActiveTurn,
    ) -> None:
        structlogger.exception(
            "a2a_server.rasa_a2a_agent_executor.execute.failed",
            task_id=task_id,
            context_id=context_id,
        )
        if turn.output_channel is not None:
            await self._finish_cancel_after_message_if_signaled(
                context_id,
                turn.output_channel,
                bound.engine_adapter,
            )
        if turn.output_channel is None or not turn.output_channel.task_cycle_closed:
            await publish_task_failure(
                turn.updater, message=_HANDLE_MESSAGE_FAILED_ERROR
            )
            turn.published_terminal_state = TaskState.TASK_STATE_FAILED

    # -- ``cancel()`` helpers ----------------------------------------------------

    def _cancel_context_id(self, context: RequestContext) -> str | None:
        if context.context_id:
            return context.context_id
        return None

    async def _cancel_signal_in_flight_turn(
        self, context_id: str, task_id: str | None
    ) -> bool:
        """Interrupt in-flight ``execute()`` for ``task_id``.

        Returns ``True`` when the task was in flight and signaled.
        """
        if not task_id:
            return False
        active_turn = await self._get_active_turn(task_id)
        if active_turn is None:
            return False
        structlogger.debug(
            "a2a_server.rasa_a2a_agent_executor.cancel.in_flight",
            task_id=task_id,
            context_id=context_id,
        )
        await self._interrupt_in_flight_turn(task_id)
        return True

    async def _cancel_idle_context(
        self,
        context_id: str,
        task_id: str | None,
        event_queue: EventQueue,
    ) -> None:
        """Run orchestrator cancel on an idle task (no in-flight ``execute()``)."""
        if not task_id:
            return
        # Snapshot before the enqueue await. A swap in that window must not
        # run readiness against one model and cancel against another.
        agent = self._agent
        engine_adapter = self._engine_adapter
        structlogger.debug(
            "a2a_server.rasa_a2a_agent_executor.cancel.idle_context",
            task_id=task_id,
            context_id=context_id,
        )
        if not agent.is_ready() or agent.processor is None:
            return
        await self._cancel_run_orchestrator_turn(
            context_id, task_id, event_queue, engine_adapter
        )

    async def _cancel_run_orchestrator_turn(
        self,
        context_id: str,
        task_id: str,
        event_queue: EventQueue,
        engine_adapter: A2AEngineAdapter,
    ) -> None:
        await event_queue.enqueue_event(
            Task(
                id=task_id,
                context_id=context_id,
                status=TaskStatus(state=TaskState.TASK_STATE_SUBMITTED),
            )
        )
        updater = TaskUpdater(event_queue, task_id, context_id)
        output_channel = A2AOutputChannel(
            updater,
            context_id,
            engine_adapter=engine_adapter,
        )
        output_channel.begin_orchestrator_cancel_turn()
        await engine_adapter.cancel_active_work(context_id, output_channel)
        await self._release_context_after_idle_cancel(context_id, output_channel)

    async def _release_context_after_idle_cancel(
        self,
        context_id: str,
        output_channel: A2AOutputChannel,
    ) -> None:
        """Release a reserved ``context_id`` after idle ``tasks/cancel``.

        ``execute()`` normally calls ``context_guard.end_turn`` from
        ``_finalize_turn``. Idle cancel publishes ``canceled`` without an
        in-flight ``execute()``, so an ``input_required`` session would otherwise
        stay counted until ``close()``.
        """
        if not output_channel.task_cycle_closed:
            return
        if output_channel.published_task_state != TaskState.TASK_STATE_CANCELED:
            return
        if self.get_active_task_ids_for_context(context_id):
            return
        await self._context_guard.end_turn(
            context_id, terminal_state=TaskState.TASK_STATE_CANCELED
        )
